from pathlib import Path
import json,csv,base64
p=Path(__file__).resolve().parents[1]
results=json.loads((p/'physics-results.json').read_text())
data={}
for case in ['stand','step','push']:
    with (p/(case+'-telemetry.csv')).open() as f:
        data[case]=[{k:(v=='True' if v in ['True','False'] else float(v)) for k,v in row.items()} for row in csv.DictReader(f)]
clips={c:'data:video/mp4;base64,'+base64.b64encode((p/(c+'.mp4')).read_bytes()).decode() for c in data}
table=''.join(f'<tr><td>{r["phone_mass_g"]:.0f} g</td><td>{r["friction"]:.1f}</td><td>{r["final_x_m"]*100:.1f} cm</td><td>{r["peak_actuator_Nm"]:.2f} Nm</td></tr>' for r in [results[3],results[1],results[4],results[5]])
html='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Phone biped · Physics lab</title><style>
*{box-sizing:border-box}body{margin:0;background:#eef0e9;color:#26362c;font:15px/1.6 system-ui,sans-serif}main{max-width:1180px;margin:0 auto;padding:40px 24px}small{font:11px ui-monospace,monospace;letter-spacing:.12em;text-transform:uppercase;color:#60735f}h1{font-size:clamp(30px,5vw,51px);line-height:1.1;letter-spacing:-.05em;margin:12px 0}header p{max-width:740px;color:#62725f}.tabs{display:flex;gap:8px;flex-wrap:wrap;margin:26px 0 16px}button{padding:11px 16px;border:1px solid #bfcaba;border-radius:8px;color:#29412e;background:transparent;font:13px system-ui;cursor:pointer}button[aria-pressed=true]{background:#284332;color:#fff}video{width:100%;display:block;background:#111b16;border-radius:12px}button:focus-visible{outline:3px solid #6d946a;outline-offset:2px}.player{background:#111b16;padding:8px;border-radius:17px}.bar{display:flex;justify-content:space-between;gap:12px;align-items:center;padding:12px;color:#c4d7bf;font:12px ui-monospace,monospace}.bar button{color:#e5f0df;border-color:#4b674e}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:18px 0}.metric,.card{background:#fafbf5;border:1px solid #cfd8c9;border-radius:12px;padding:20px}.metric strong{display:block;font-size:29px;letter-spacing:-.04em}.metric small{font-size:9px;letter-spacing:.03em}h2{font-size:23px;line-height:1.25;letter-spacing:-.03em;margin:8px 0 14px}.columns{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-top:16px}.card p,.card li{font-size:13px;color:#596c55}.card ul{padding-left:18px}.card li{margin:8px 0}.readout{font:12px ui-monospace,monospace;color:#476443;min-height:44px}table{border-collapse:collapse;width:100%;font-size:12px}th,td{text-align:left;border-bottom:1px solid #dbe2d5;padding:9px 5px}th{color:#63755e;font-weight:500}footer{font-size:11px;color:#667b60;margin-top:24px}a{color:inherit}#result{font-size:14px;color:#465e42}input{accent-color:#92bb88}@media(max-width:650px){main{padding:25px 14px}.columns{grid-template-columns:1fr}.grid{grid-template-columns:1fr 1fr}.metric{padding:14px}.metric strong{font-size:25px}.bar{font-size:10px;flex-wrap:wrap}}
</style></head><body><main><header><small>Product anatomy / physics experiment 01</small><h1>Let gravity have a say.</h1><p>Your phone-carrying biped, tested with rigid-body dynamics, torque-limited joints, friction and floor contact in MuJoCo. These are recorded physics runs; the browser plays the results rather than recomputing the simulation.</p></header>
<div class="tabs" role="group" aria-label="Choose a physics test"><button data-case="stand" aria-pressed="true">01 · Stand & turn phone</button><button data-case="step" aria-pressed="false">02 · Stepping attempt</button><button data-case="push" aria-pressed="false">03 · Push & fall</button></div>
<section class="player"><video id="video" controls playsinline preload="metadata" aria-label="Recorded robot physics simulation"></video><div class="bar"><span id="label">6 seconds · free-floating body · no supporting tether</span><button id="slow" aria-pressed="false">Slow motion · ¼ speed</button><button id="restart">Replay from start</button></div></section>
<div class="grid"><div class="metric"><strong id="clock">0.00 s</strong><small>Simulation time</small></div><div class="metric"><strong id="travel">0.0 cm</strong><small>Pelvis forward displacement</small></div><div class="metric"><strong id="tilt">0.0°</strong><small>Body tilt from upright</small></div><div class="metric"><strong id="torque">0.00 Nm</strong><small>Largest current joint torque</small></div></div>
<div class="readout" id="contacts" aria-live="off">Press play to inspect the simulated movement.</div>
<section class="card"><small>What this test shows</small><h2 id="title"></h2><p id="result"></p></section>
<div class="columns"><section class="card"><small>Assumed prototype</small><h2>A model we can change.</h2><ul><li>14 actuated axes: six per leg, plus phone pan and tilt.</li><li>250 g phone, approximately 1.691 kg total mass. Total includes a 1 g screen proxy.</li><li>80 mm thigh and shin links; 96 × 60 mm soles, 106 mm foot-centre spacing. About 370 mm overall height.</li><li>Leg torques limited to ±1.5 Nm; neck torques to ±0.25 Nm. Ideal position servos with damping; no measured motor model.</li><li>Gravity 9.81 m/s²; nominal sliding friction coefficient 0.8; 2 ms physics timestep; six seconds per test.</li></ul></section>
<section class="card"><small>Same controller / different assumptions</small><h2>Mass and grip change the result.</h2><table><thead><tr><th>Phone</th><th>Friction</th><th>Travel</th><th>Peak torque</th></tr></thead><tbody>TABLE</tbody></table><p>These stepping runs remain upright for the six-second window. Extra movement on the slippery floor can include sliding; distance alone is not a walking-quality score. Peak torque is a simulation observation, not a motor recommendation.</p><p>At nominal friction, exactly one sole contacts the floor in approximately 12% of sampled frames. Much of this early gait keeps both feet in contact.</p></section>
<section class="card"><small>Checks performed</small><h2>Physics, with practical limits.</h2><p>The standing ground reaction averages 16.589 N, matching model weight. Torque limits hold. Reducing the timestep from 2 ms to 1 ms changes stepping distance from 9.78 cm to 9.39 cm (4.0%).</p><p>Fall detection: body tilt exceeds 45° or pelvis height drops below 100 mm. The push is a 12 N horizontal force at the pelvis centre of mass for 160 ms, starting at t = 2 s.</p><p>This is a useful first dynamics experiment, with short test durations and simplified geometry. It does not establish robust balance or a production-ready gait.</p></section>
<section class="card"><small>Next engineering pass</small><h2>From a shuffle to reliable walking.</h2><ul><li>Replace estimated masses, inertias and joint locations with CAD and measured phone properties.</li><li>Add IMU and foot-load feedback, body-weight transfer, foot trajectory planning and push recovery.</li><li>Model backlash, torque–speed curves, power limits, thermal behaviour and delays.</li><li>Enable robot self-collision after refining link collision geometry. This first model checks robot–floor collisions only.</li><li>Test turning steps, target tracking, obstacles, floor edges and a wider range of surfaces. Those behaviours are not yet simulated.</li></ul></section></div>
<footer>Reproduce or modify the physics with the included <a href="simulate_robot.py">simulation script</a> and <a href="phone-biped-model.xml">MuJoCo model</a>. Read the <a href="physics-results.json">run summaries</a> and <a href="physics-checks.json">numerical checks</a>. Engine: <a href="https://mujoco.readthedocs.io/en/stable/modeling.html">MuJoCo</a>. The animation is generated from simulated body positions; no root trajectory is imposed.</footer>
</main><script>
const clips=CLIPS,data=DATA;let current='stand';
const summaries={stand:['Standing and turning the phone works in this model.','The body remains upright throughout the six-second test while the neck pans. Maximum body tilt is 0.02°. This symmetric, level-floor test is much easier than real-world standing under disturbances.'],step:['The first movement is a shuffle, not a finished gait.','The simple joint controller moves the pelvis 9.8 cm forward over six seconds, with 1.8° maximum tilt. It has no online body-balance feedback. Some frames lift a foot; much of the movement uses double contact and may include slip.'],push:['The current controller cannot recover from this push.','A 12 N push starts at two seconds and lasts 160 ms. The model meets the fall criterion at 2.236 seconds. The leg servos reach their 1.5 Nm limit; the robot has no recovery-step strategy.']};
const video=document.querySelector('#video');
function readings(){const rows=data[current];const t=video.currentTime;const r=rows[Math.min(rows.length-1,Math.round(t/.02))];document.querySelector('#clock').textContent=t.toFixed(2)+' s';document.querySelector('#travel').textContent=(r.x_m*100).toFixed(1)+' cm';document.querySelector('#tilt').textContent=r.tilt_deg.toFixed(1)+'°';document.querySelector('#torque').textContent=r.max_actuator_Nm.toFixed(2)+' Nm';document.querySelector('#contacts').textContent='Ground contact: left '+(r.left_contact?'yes':'no')+' / right '+(r.right_contact?'yes':'no')+' · normal load '+r.left_normal_N.toFixed(1)+' / '+r.right_normal_N.toFixed(1)+' N · telemetry sampled every 20 ms';}
function choose(c,play=false){current=c;video.pause();video.src=clips[c];video.load();document.querySelectorAll('[data-case]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.case===c)));document.querySelector('#title').textContent=summaries[c][0];document.querySelector('#result').textContent=summaries[c][1];readings();if(play)video.play().catch(()=>{});}
document.querySelectorAll('[data-case]').forEach(b=>b.onclick=()=>choose(b.dataset.case,true));video.ontimeupdate=readings;video.onseeked=readings;
document.querySelector('#slow').onclick=e=>{const slow=video.playbackRate===1;video.playbackRate=slow?.25:1;e.target.setAttribute('aria-pressed',String(slow));e.target.textContent=slow?'Normal speed':'Slow motion · ¼ speed'};
document.querySelector('#restart').onclick=()=>{video.currentTime=0;video.play().catch(()=>{})};choose('stand');
</script></body></html>'''
html=html.replace('TABLE',table).replace('CLIPS',json.dumps(clips)).replace('DATA',json.dumps(data))
(p/'phone-biped-physics.html').write_text(html,encoding='utf-8')
print('Built physics replay with embedded videos and telemetry.')
